// Obtenemos el valor de 'respuesta_definitiva' desde el input
const respuestaDefinitiva = $input.first().json.body.custom_fields.respuesta_definitiva || '';

// Función para separar el texto y detectar múltiples enlaces
function separarMensaje(texto) {
    // Si no hay texto, devolvemos valores vacíos
    if (!texto) {
        return {
            texto: '',
            audio: []
        };
    }

    // Regex combinada para audios:
    // - manybot S3
    // - Facebook / Instagram CDN (lookaside)
    const urlRegex = /https:\/\/manybot-files\.s3\.eu-central-1\.amazonaws\.com\/[^,\s]+|https:\/\/lookaside\.fbsbx\.com\/ig_messaging_cdn\/\?[^,\s]+/g;

    const matches = texto.match(urlRegex) || [];

    // Limpieza del texto (sin links ni comas)
    const textoLimpio = texto
        .replace(urlRegex, '')
        .replace(/,/g, '')
        .trim();

    return {
        texto: textoLimpio,
        audio: matches
    };
}

// Llamamos a la función y devolvemos el resultado
return separarMensaje(respuestaDefinitiva);

// n8n Code node (JS) - soporta múltiples inputs

const in0 = $input.all(0); // rama "Juntar mensajes"
const in1 = $input.all(1); // rama "Obtener solo texto"

// helper para extraer el campo (por si cambia el nombre)
function getMsg(item) {
  return (
    item?.json?.["Mensaje completo"] ??
    item?.json?.mensaje_completo ??
    item?.json?.text ??
    item?.json?.texto ??
    ""
  );
}

// 1) si solo llegó una rama, usar esa
if (in0.length && !in1.length) {
  return in0.map(i => ({ json: { "Mensaje completo": getMsg(i) } }));
}
if (in1.length && !in0.length) {
  return in1.map(i => ({ json: { "Mensaje completo": getMsg(i) } }));
}

// 2) si llegaron ambas (raro, pero pasa), elegir el que tenga contenido (o el más largo)
const maxLen = Math.max(in0.length, in1.length);

const out = [];
for (let idx = 0; idx < maxLen; idx++) {
  const a = getMsg(in0[idx] ?? in0[0] ?? {});
  const b = getMsg(in1[idx] ?? in1[0] ?? {});
  const aOk = (a || "").trim();
  const bOk = (b || "").trim();

  // prioriza: no vacío; si ambos no vacíos, el más largo
  const chosen =
    aOk && bOk ? (aOk.length >= bOk.length ? aOk : bOk) :
    aOk ? aOk :
    bOk ? bOk :
    "";

  out.push({ json: { "Mensaje completo": chosen } });
}

return out;
